'use client';

import React, { useState, useMemo } from 'react';
import { useApp, isValidYouTubeUrl } from '@/context/AppContext';
import { Classroom, Meeting, User } from '@/types';

export default function MeetingJournal() {
  const {
    currentUser,
    users,
    classrooms,
    meetings,
    addMeeting,
    updateMeeting,
    clearMeetingSlot,
    toggleLockMeeting,
    lockEmptySlot,
    selectedMonth,
    setSelectedMonth,
    isJournalLocked,
    toggleJournalLock,
    toggleLockMonth,
    isMonthLocked,
  } = useApp();

  const isAdmin = currentUser?.role === 'admin';

  // Periksa apakah bulan yang sedang dibuka ini berstatus terkunci
  const isPeriodLocked = isMonthLocked(selectedMonth);

  // 1. Tab Kategori Program (Termasuk Fee Assist)
  const tabTypes: { id: string; label: string }[] = [
    { id: 'all', label: 'Semua Program' },
    { id: 'Kids-A', label: 'Kids-A' },
    { id: 'Kids-B', label: 'Kids-B' },
    { id: 'SPL-A', label: 'SPL-A' },
    { id: 'SPL-B', label: 'SPL-B' },
    { id: 'Group', label: 'Group' },
    { id: 'Test Prep-A', label: 'Test Prep-A (1.5 Jam)' },
    { id: 'Test Prep-B', label: 'Test Prep-B (1 Jam)' },
    { id: 'Social Banjar/Panti', label: 'Social/Panti' },
    { id: 'Assist', label: 'Fee Assist' },
  ];
  const [activeTabType, setActiveTabType] = useState<string>('all');

  // 2. Search Nama Murid / Kelas
  const [searchStudent, setSearchStudent] = useState<string>('');

  // 3. Filter Tutor (Khusus Admin untuk Audit Cek Fakta)
  const [selectedTutorId, setSelectedTutorId] = useState<string>('');

  // 4. State Modal Pengisian Sesi Kosong
  const [activeSlot, setActiveSlot] = useState<{ classId: string; meetingNumber: number } | null>(null);
  const [inputDate, setInputDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [inputLesson, setInputLesson] = useState<string>('');
  const [inputNotes, setInputNotes] = useState<string>('');
  const [inputVideoUrl, setInputVideoUrl] = useState<string>('');

  // 5. State Modal Edit Sesi untuk Admin (Human Error Correction)
  const [editingMeeting, setEditingMeeting] = useState<Meeting | null>(null);
  const [editDate, setEditDate] = useState<string>('');
  const [editLesson, setEditLesson] = useState<string>('');
  const [editNotes, setEditNotes] = useState<string>('');
  const [editTutorId, setEditTutorId] = useState<string>('');
  const [editVideoUrl, setEditVideoUrl] = useState<string>('');
  const [editLdrZone, setEditLdrZone] = useState<string>('none');

  // 6. State Modal Baca Selengkapnya untuk Catatan/Note Siswa
  const [viewingNote, setViewingNote] = useState<{
    studentName: string;
    meetingNumber: number;
    cumulativeMeetingNumber: number;
    date: string;
    tutorName: string;
    lesson: string;
    notes: string;
  } | null>(null);

  // Daftar tutor untuk pilihan filter dropdown
  const tutorList = useMemo(() => {
    return users.filter((u: User) => u.role === 'tutor');
  }, [users]);

  // Filter Kelas berdasarkan Tab Program, Pencarian Murid, dan Filter Tutor Terpilih
  const filteredClassrooms: Classroom[] = useMemo(() => {
    return classrooms.filter((cls: Classroom) => {
      const matchType = activeTabType === 'all' || cls.type === activeTabType;
      const matchSearch =
        searchStudent.trim() === '' ||
        cls.name.toLowerCase().includes(searchStudent.toLowerCase()) ||
        cls.students.some((st: string) => st.toLowerCase().includes(searchStudent.toLowerCase()));

      let matchTutor = true;
      if (isAdmin && selectedTutorId) {
        matchTutor = meetings.some(
          (m: Meeting) =>
            m.classroomId === cls.id &&
            m.date?.startsWith(selectedMonth) &&
            m.tutorId === selectedTutorId
        );
      }

      return matchType && matchSearch && matchTutor;
    });
  }, [classrooms, activeTabType, searchStudent, selectedTutorId, isAdmin, meetings, selectedMonth]);

  // Perhitungan Akumulasi Sesi Riil Tutor Terpilih (Audit Counter)
  const auditTutorSessionStats = useMemo(() => {
    if (!isAdmin || !selectedTutorId) return null;

    const targetTutorMeetings = meetings.filter(
      (m: Meeting) =>
        m.date?.startsWith(selectedMonth) &&
        m.tutorId === selectedTutorId &&
        filteredClassrooms.some((cls) => cls.id === m.classroomId)
    );

    const tutorObj = users.find((u: User) => u.id === selectedTutorId);

    return {
      tutorName: tutorObj ? tutorObj.name : 'Tutor',
      totalSessions: targetTutorMeetings.length,
      totalClasses: filteredClassrooms.length,
    };
  }, [isAdmin, selectedTutorId, meetings, selectedMonth, filteredClassrooms, users]);

  const selectedClassForModal = classrooms.find((c: Classroom) => c.id === activeSlot?.classId);

  const handleOpenFillModal = (classId: string, meetingNumber: number) => {
    if (!isAdmin && (isJournalLocked || isPeriodLocked)) {
      alert(`Pengisian jurnal untuk periode ${selectedMonth} telah ditutup/dikunci oleh Admin.`);
      return;
    }
    setActiveSlot({ classId, meetingNumber });
    setInputDate(`${selectedMonth}-01`);
    setInputLesson('');
    setInputNotes('');
    setInputVideoUrl('');
  };

  const handleSubmitMeeting = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeSlot) return;
    if (!isAdmin && (isJournalLocked || isPeriodLocked)) {
      alert(`Pengisian jurnal untuk periode ${selectedMonth} telah ditutup/dikunci oleh Admin.`);
      return;
    }
    if (!inputLesson.trim()) {
      alert('Harap masukkan materi pelajaran (lesson)!');
      return;
    }

    const cleanUrl = inputVideoUrl.trim();
    if (cleanUrl !== '' && !isValidYouTubeUrl(cleanUrl)) {
      alert('Tautan video tidak valid! Harap masukkan URL YouTube yang benar (contoh: https://youtu.be/... atau https://youtube.com/watch?v=...) atau kosongkan jika tidak ada.');
      return;
    }

    const currentClass = classrooms.find((c: Classroom) => c.id === activeSlot.classId);

    await addMeeting({
      classroomId: activeSlot.classId,
      meetingNumber: activeSlot.meetingNumber,
      date: inputDate,
      lesson: inputLesson.trim(),
      notes: inputNotes.trim(),
      videoUrl: cleanUrl,
      ldrZone: currentClass?.ldrZone || 'none',
      ldrZoneSnapshot: currentClass?.ldrZone || 'none',
    });

    setActiveSlot(null);
  };

  const handleOpenEditModal = (mtg: Meeting) => {
    setEditingMeeting(mtg);
    setEditDate(mtg.date);
    setEditLesson(mtg.lesson);
    setEditNotes(mtg.notes || '');
    setEditTutorId(mtg.tutorId);
    setEditVideoUrl(mtg.videoUrl || '');
    setEditLdrZone(mtg.ldrZoneSnapshot || 'none');
  };

  const handleSaveEditMeeting = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMeeting) return;

    if (!editLesson.trim()) {
      alert('Harap masukkan materi pelajaran (lesson)!');
      return;
    }

    const cleanUrl = editVideoUrl.trim();
    if (cleanUrl !== '' && !isValidYouTubeUrl(cleanUrl)) {
      alert('Tautan video tidak valid! Harap masukkan URL YouTube yang benar (contoh: https://youtu.be/... atau https://youtube.com/watch?v=...) atau kosongkan jika tidak ada.');
      return;
    }

    const assignedTutor = users.find((u: User) => u.id === editTutorId);

    await updateMeeting(editingMeeting.id, {
      date: editDate,
      lesson: editLesson.trim(),
      notes: editNotes.trim(),
      videoUrl: cleanUrl,
      ldrZone: editLdrZone,
      ldrZoneSnapshot: editLdrZone,
      tutorId: editTutorId,
      tutorName: assignedTutor ? assignedTutor.name : editingMeeting.tutorName,
    });

    setEditingMeeting(null);
  };

  const handleClearSlot = async (classroomId: string, meetingNumber: number) => {
    if (confirm(`Yakin ingin mengosongkan/menghapus isi sesi pertemuan #${meetingNumber}? Kolom akan bersih kembali.`)) {
      await clearMeetingSlot(classroomId, meetingNumber);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header Halaman & Filter Bulan Jurnal */}
      <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Lembar Jurnal Mengajar</h2>
          <p className="text-xs text-slate-500 mt-1">
            Format spreadsheet matriks per murid. Menampilkan aktivitas bulan <strong>{selectedMonth}</strong> secara default.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          {/* SAKLAR KONTROL ADMIN (KUNCI PERIODE BULAN TERPILIH) */}
          {isAdmin && (
            <button
              onClick={() => toggleLockMonth(selectedMonth)}
              className={`px-3.5 py-2 rounded-xl text-xs font-bold transition-all shadow-sm flex items-center gap-2 border ${
                isPeriodLocked
                  ? 'bg-rose-50 text-rose-700 border-rose-300 hover:bg-rose-100'
                  : 'bg-emerald-50 text-emerald-700 border-emerald-300 hover:bg-emerald-100'
              }`}
              title="Klik untuk mengunci atau membuka akses pengisian jurnal di bulan ini bagi tutor"
            >
              <span>{isPeriodLocked ? '🔒' : '🔓'}</span>
              <span>{isPeriodLocked ? `Bulan ${selectedMonth}: TERKUNCI` : `Bulan ${selectedMonth}: TERBUKA`}</span>
            </button>
          )}

          {/* SAKLAR AUDIT GLOBAL SEMENTARA */}
          {isAdmin && (
            <button
              onClick={toggleJournalLock}
              className={`px-3 py-2 rounded-xl text-xs font-semibold transition-all border ${
                isJournalLocked
                  ? 'bg-amber-100 text-amber-900 border-amber-300'
                  : 'bg-slate-50 text-slate-600 border-slate-200 hover:bg-slate-100'
              }`}
              title="Kunci global seluruh form pengisian untuk audit dadakan"
            >
              {isJournalLocked ? '⚠️ Audit Global: AKTIF' : 'Audit Global: Non-aktif'}
            </button>
          )}

          {/* Pemilih Periode Bulan Jurnal */}
          <div className="flex items-center gap-2 bg-slate-50 p-1.5 rounded-xl border border-slate-200">
            <span className="text-xs font-semibold text-slate-600 pl-1">Periode:</span>
            <input
              type="month"
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(e.target.value)}
              className="px-3 py-1.5 text-xs border rounded-lg bg-white font-semibold text-slate-800 outline-none focus:ring-2 focus:ring-amber-500"
            />
          </div>
        </div>
      </div>

      {/* BANNER NOTIFIKASI BULAN INI TERKUNCI (SISI TUTOR) */}
      {!isAdmin && isPeriodLocked && (
        <div className="p-4 bg-rose-50 border border-rose-200 rounded-2xl flex items-center gap-3 text-rose-900 animate-in fade-in">
          <span className="text-2xl">🔒</span>
          <div>
            <h4 className="font-bold text-xs">Periode Bulan Ini Telah Ditutup (Read-Only)</h4>
            <p className="text-[11px] text-rose-800/80 mt-0.5">
              Admin telah mengunci pencatatan jurnal untuk periode <strong>{selectedMonth}</strong>. Data pada bulan ini hanya dapat dilihat untuk arsip dan tidak dapat ditambah atau diubah oleh tutor.
            </p>
          </div>
        </div>
      )}

      {/* BANNER NOTIFIKASI AUDIT GLOBAL JIKA AKTIF */}
      {!isAdmin && !isPeriodLocked && isJournalLocked && (
        <div className="p-4 bg-amber-50 border border-amber-200 rounded-2xl flex items-center gap-3 text-amber-900 animate-in fade-in">
          <span className="text-2xl">🔒</span>
          <div>
            <h4 className="font-bold text-xs">Akses Pengisian Jurnal Sedang Ditutup (Audit Mode)</h4>
            <p className="text-[11px] text-amber-800/80 mt-0.5">
              Admin sedang melakukan peninjauan sesi. Tombol pengisian sesi baru sementara dinonaktifkan.
            </p>
          </div>
        </div>
      )}

      {/* Kontrol Tab Program & Search Murid & Filter Tutor */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm space-y-3">
        {/* Tab Program */}
        <div className="flex items-center gap-2 overflow-x-auto pb-1">
          <span className="text-xs text-slate-400 font-semibold shrink-0 mr-1">Program Sheet:</span>
          {tabTypes.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTabType(tab.id)}
              className={`px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all ${
                activeTabType === tab.id
                  ? 'bg-amber-500 text-white shadow-sm'
                  : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Baris Pencarian: Input Nama Murid + Filter Dropdown Tutor (Admin) + Badge Counter */}
        <div className="flex flex-col md:flex-row items-center gap-3 pt-1">
          <div className="relative flex-1 w-full">
            <input
              type="text"
              placeholder="Ketik nama murid untuk mencari (misal: Ayu Widya)..."
              value={searchStudent}
              onChange={(e) => setSearchStudent(e.target.value)}
              className="w-full pl-9 pr-8 py-2 text-xs border border-slate-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-amber-500"
            />
            <span className="absolute left-3 top-2.5 text-xs text-slate-400">🔍</span>
            {searchStudent && (
              <button
                onClick={() => setSearchStudent('')}
                className="absolute right-3 top-2.5 text-xs text-slate-400 hover:text-slate-600"
              >
                ✕
              </button>
            )}
          </div>

          {isAdmin && (
            <div className="w-full md:w-64 shrink-0">
              <select
                value={selectedTutorId}
                onChange={(e) => setSelectedTutorId(e.target.value)}
                className="w-full px-3 py-2 text-xs border border-slate-300 rounded-xl bg-white font-semibold text-slate-700 outline-none focus:ring-2 focus:ring-amber-500 cursor-pointer shadow-sm"
              >
                <option value="">👤 Semua Tutor Pengajar</option>
                {tutorList.map((tutor) => (
                  <option key={tutor.id} value={tutor.id}>
                    {tutor.name}
                  </option>
                ))}
              </select>
            </div>
          )}

          <div className="flex items-center gap-2 px-3.5 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 shrink-0 self-stretch md:self-auto justify-center">
            {auditTutorSessionStats ? (
              <span className="text-amber-700 flex items-center gap-1.5">
                <span>🎯</span>
                <span>
                  {auditTutorSessionStats.totalSessions} Sesi Terisi ({auditTutorSessionStats.totalClasses} Kelas)
                </span>
              </span>
            ) : (
              <span className="text-slate-600">
                {filteredClassrooms.length} Kelas Ditampilkan
              </span>
            )}
          </div>
        </div>
      </div>

      {/* Grid Tabel Matriks Jurnal */}
      {filteredClassrooms.length === 0 ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center text-slate-400 text-sm">
          {selectedTutorId
            ? `Tidak ada sesi mengajar untuk tutor ini di bulan ${selectedMonth}.`
            : `Tidak ditemukan murid atau kelas yang cocok dengan pencarian "${searchStudent}".`}
        </div>
      ) : (
        <div className="space-y-6">
          {filteredClassrooms.map((cls: Classroom) => {
            // Sesi yang ada di bulan terpilih
            const classMeetings: Meeting[] = meetings.filter(
              (m: Meeting) => m.classroomId === cls.id && m.date?.startsWith(selectedMonth)
            );

            // TITIK AWAL SISTEM BARU (BASELINE NOVEMBER 2026):
            // Jika yang dibuka adalah November 2026 atau sebelumnya, baseCumulativeCount = 0 (semua mulai dari 1)
            let baseCumulativeCount = 0;

            if (selectedMonth > '2026-11') {
              const pastMeetings = meetings.filter(
                (m: Meeting) =>
                  m.classroomId === cls.id &&
                  m.date &&
                  m.date >= '2026-11-01' && // Hanya hitung riwayat yang terjadi mulai November 2026
                  m.date < `${selectedMonth}-01` &&
                  !m.isLocked &&
                  m.lesson &&
                  m.lesson !== 'Sesi Dikosongkan / Hangus oleh Admin'
              );

              const maxPastMeetingNumber =
                pastMeetings.length > 0
                  ? Math.max(...pastMeetings.map((m: Meeting) => m.meetingNumber))
                  : 0;

              baseCumulativeCount = Math.max(pastMeetings.length, maxPastMeetingNumber);
            }

            const highestMeetingNum =
              classMeetings.length > 0
                ? Math.max(...classMeetings.map((m: Meeting) => m.meetingNumber))
                : 0;
            const totalCols = Math.max(cls.totalMeetings || 4, highestMeetingNum, 4);
            const colIndexes: number[] = Array.from({ length: totalCols }, (_, i) => i + 1);

            return (
              <div
                key={cls.id}
                className="bg-white rounded-2xl border border-slate-300 shadow-sm overflow-hidden"
              >
                {/* HEADER KOTAK KELAS & NAMA MURID */}
                <div className="p-4 bg-slate-50/80 border-b border-slate-200 flex flex-wrap items-center justify-between gap-4">
                  <div className="flex items-start md:items-center gap-3.5">
                    <span className="px-3 py-1.5 bg-amber-500 text-white font-black text-xs uppercase rounded-lg tracking-wider shrink-0 shadow-sm">
                      CLASS
                    </span>
                    <div>
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="text-xs font-semibold text-slate-400 uppercase tracking-wide">
                          Murid:
                        </span>
                        <h3 className="text-lg md:text-xl font-black text-slate-900 tracking-tight">
                          {cls.students.join(', ')}
                        </h3>
                      </div>

                      <div className="flex items-center gap-2 text-xs text-slate-500 mt-1 flex-wrap">
                        <span className="font-semibold text-slate-700 bg-white px-2.5 py-0.5 rounded-md border border-slate-200">
                          {cls.name}
                        </span>
                        <span>•</span>
                        <span className="font-bold text-amber-800 bg-amber-50 px-2.5 py-0.5 rounded-md border border-amber-200">
                          Program: {cls.type}
                        </span>
                        <span>•</span>
                        <span className="font-semibold text-slate-600 bg-slate-100 px-2 py-0.5 rounded">
                          Bulan: {selectedMonth}
                        </span>
                        {cls.ldrZone !== 'none' && (
                          <>
                            <span>•</span>
                            <span className="font-semibold text-purple-700 bg-purple-50 px-2.5 py-0.5 rounded-md border border-purple-200">
                              📍 {cls.ldrZone.replace('_', ' >').toUpperCase()} KM
                            </span>
                          </>
                        )}
                      </div>
                    </div>
                  </div>
                </div>

                {/* Tabel Matriks Horizontal */}
                <div className="overflow-x-auto">
                  <table className="w-full text-xs text-left border-collapse min-w-[750px]">
                    <tbody>
                      {/* Baris 1: Meet This Month (Pertemuan di Bulan Berjalan) */}
                      <tr className="border-b border-slate-200">
                        <td className="w-44 py-2.5 px-4 font-bold bg-amber-100 text-slate-800 border-r border-slate-300">
                          Meet This Month
                        </td>
                        {colIndexes.map((num: number) => (
                          <td
                            key={num}
                            className="py-2.5 px-3 text-center font-bold bg-rose-50 text-slate-800 border-r border-slate-200 min-w-[145px]"
                          >
                            {num}
                          </td>
                        ))}
                      </tr>

                      {/* Baris 2: Class meetings (Kumulatif Bersambung dari Bulan Lalu) */}
                      <tr className="border-b border-slate-200">
                        <td className="py-2.5 px-4 font-bold bg-amber-100 text-slate-800 border-r border-slate-300">
                          <div>Class meetings</div>
                          <span className="text-[9px] font-normal text-slate-500 block leading-tight">
                            (Total Pertemuan Riil)
                          </span>
                        </td>
                        {colIndexes.map((num: number) => {
                          const cumulativeMeetingNum = baseCumulativeCount + num;
                          return (
                            <td
                              key={num}
                              className="py-2.5 px-3 text-center font-extrabold text-amber-900 bg-amber-50/50 border-r border-slate-200"
                            >
                              #{cumulativeMeetingNum}
                            </td>
                          );
                        })}
                      </tr>

                      {/* Baris 3: Date */}
                      <tr className="border-b border-slate-200">
                        <td className="py-2.5 px-4 font-bold bg-amber-100 text-slate-800 border-r border-slate-300">
                          Date
                        </td>
                        {colIndexes.map((num: number) => {
                          const mtg = classMeetings.find((m: Meeting) => m.meetingNumber === num);
                          return (
                            <td
                              key={num}
                              className="py-2 px-3 text-center text-slate-700 border-r border-slate-200 font-medium"
                            >
                              {mtg ? (
                                <span className="bg-slate-100 px-2 py-0.5 rounded text-[11px]">
                                  {mtg.date}
                                </span>
                              ) : (
                                <span className="text-slate-300">-</span>
                              )}
                            </td>
                          );
                        })}
                      </tr>

                      {/* Baris 4: Tutor */}
                      <tr className="border-b border-slate-200">
                        <td className="py-2.5 px-4 font-bold bg-amber-100 text-slate-800 border-r border-slate-300">
                          Tutor
                        </td>
                        {colIndexes.map((num: number) => {
                          const mtg = classMeetings.find((m: Meeting) => m.meetingNumber === num);
                          const isHighlighted = selectedTutorId && mtg?.tutorId === selectedTutorId;

                          return (
                            <td
                              key={num}
                              className={`py-2 px-3 text-center border-r border-slate-200 font-semibold ${
                                isHighlighted
                                  ? 'bg-amber-100/60 text-amber-900 font-bold'
                                  : 'text-slate-800'
                              }`}
                            >
                              {mtg ? mtg.tutorName : <span className="text-slate-300">-</span>}
                            </td>
                          );
                        })}
                      </tr>

                      {/* Baris 5: Lesson, Status, Notes (Modal Detail), Edit & Reset */}
                      <tr>
                        <td className="py-3 px-4 font-bold bg-amber-100 text-slate-800 border-r border-slate-300">
                          Lesson &amp; Note
                        </td>
                        {colIndexes.map((num: number) => {
                          const mtg = classMeetings.find((m: Meeting) => m.meetingNumber === num);
                          const mtgLdr = mtg?.ldrZoneSnapshot;
                          const cumulativeMeetingNum = baseCumulativeCount + num;

                          return (
                            <td
                              key={num}
                              className="py-2.5 px-3 border-r border-slate-200 text-slate-700 align-top"
                            >
                              {mtg ? (
                                <div className="space-y-1.5">
                                  <p className="font-semibold text-slate-800 leading-snug">{mtg.lesson}</p>

                                  {/* PREVIEW CATATAN + TOMBOL BACA SELENGKAPNYA */}
                                  {mtg.notes && (
                                    <div>
                                      <p className="text-[10px] text-slate-500 italic line-clamp-2 leading-relaxed">
                                        &ldquo;{mtg.notes}&rdquo;
                                      </p>
                                      {mtg.notes.length > 50 && (
                                        <button
                                          type="button"
                                          onClick={() =>
                                            setViewingNote({
                                              studentName: cls.students.join(', '),
                                              meetingNumber: num,
                                              cumulativeMeetingNumber: cumulativeMeetingNum,
                                              date: mtg.date,
                                              tutorName: mtg.tutorName,
                                              lesson: mtg.lesson,
                                              notes: mtg.notes || '',
                                            })
                                          }
                                          className="text-[10px] text-amber-600 hover:text-amber-800 font-bold hover:underline inline-block mt-0.5"
                                        >
                                          Baca Selengkapnya
                                        </button>
                                      )}
                                    </div>
                                  )}

                                  <div className="flex items-center gap-1 flex-wrap pt-0.5">
                                    {mtg.videoUrl ? (
                                      <a
                                        href={mtg.videoUrl}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="inline-flex items-center gap-1 text-[9px] font-bold text-rose-700 bg-rose-50 hover:bg-rose-100 border border-rose-200 px-1.5 py-0.5 rounded transition-colors"
                                        title="Buka Video di YouTube"
                                      >
                                        ▶️ Video YT
                                      </a>
                                    ) : (
                                      mtg.hasVideoClaim && (
                                        <span className="inline-flex items-center gap-1 text-[9px] font-bold text-amber-800 bg-amber-100 px-1.5 py-0.5 rounded">
                                          🎬 Video
                                        </span>
                                      )
                                    )}

                                    {mtgLdr && mtgLdr !== 'none' && (
                                      <span className="inline-flex items-center gap-1 text-[9px] font-bold text-purple-800 bg-purple-100 px-1.5 py-0.5 rounded">
                                        📍 {mtgLdr.replace('_', ' >').toUpperCase()} KM
                                      </span>
                                    )}

                                    {mtg.isLocked && (
                                      <span className="inline-block text-[9px] font-bold text-rose-600 bg-rose-100 px-1.5 py-0.5 rounded border border-rose-200">
                                        🔒 Terkunci / Hangus
                                      </span>
                                    )}
                                  </div>

                                  {/* KONTROL EDIT KHUSUS ADMIN */}
                                  {isAdmin && (
                                    <div className="pt-1.5 flex items-center gap-2 border-t border-slate-100">
                                      <button
                                        onClick={() => handleOpenEditModal(mtg)}
                                        className="text-[10px] text-amber-600 hover:text-amber-800 font-semibold hover:underline"
                                      >
                                        ✏️ Edit
                                      </button>
                                      <span className="text-slate-300 text-[10px]">•</span>
                                      <button
                                        onClick={() => handleClearSlot(cls.id, num)}
                                        className="text-[10px] text-rose-600 hover:text-rose-800 font-semibold hover:underline"
                                      >
                                        🗑️ Kosongkan
                                      </button>
                                      <span className="text-slate-300 text-[10px]">•</span>
                                      <button
                                        onClick={() => toggleLockMeeting(mtg.id)}
                                        className="text-[10px] text-slate-500 hover:text-slate-700 hover:underline"
                                      >
                                        {mtg.isLocked ? 'Buka' : 'Kunci'}
                                      </button>
                                    </div>
                                  )}
                                </div>
                              ) : (
                                /* KOLOM KOSONG DI BULAN INI */
                                <div className="space-y-1.5">
                                  {!isAdmin && (isJournalLocked || isPeriodLocked) ? (
                                    <div className="w-full py-1 text-[10px] text-slate-400 bg-slate-50 border border-slate-200 rounded text-center font-medium">
                                      🔒 {isPeriodLocked ? 'Bulan Ditutup' : 'Audit Mode'}
                                    </div>
                                  ) : (
                                    <button
                                      onClick={() => handleOpenFillModal(cls.id, num)}
                                      className="w-full py-1 text-[11px] text-emerald-700 bg-emerald-50 hover:bg-emerald-100 border border-dashed border-emerald-300 rounded font-semibold transition-all"
                                    >
                                      + Isi Sesi #{num}
                                    </button>
                                  )}

                                  {isAdmin && (
                                    <button
                                      onClick={() => lockEmptySlot(cls.id, num)}
                                      className="w-full py-0.5 text-[10px] text-rose-600 hover:text-rose-800 hover:bg-rose-50 rounded transition-all flex items-center justify-center gap-1"
                                      title="Kunci sesi ini agar hangus"
                                    >
                                      <span>🔒</span> Kunci Slot
                                    </button>
                                  )}
                                </div>
                              )}
                            </td>
                          );
                        })}
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* MODAL 1: INPUT JURNAL BARU */}
      {activeSlot && selectedClassForModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl max-w-md w-full p-6 shadow-2xl space-y-4 animate-in fade-in zoom-in-95 duration-150 max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between border-b pb-3">
              <div>
                <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">
                  Input Jurnal Mengajar
                </span>
                <h3 className="font-black text-slate-900 text-lg leading-snug">
                  {selectedClassForModal.students.join(', ')}
                </h3>
                <p className="text-xs text-slate-500">
                  Kelas: {selectedClassForModal.name} ({selectedClassForModal.type})
                </p>
              </div>
              <button
                onClick={() => setActiveSlot(null)}
                className="text-slate-400 hover:text-slate-600 text-lg"
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleSubmitMeeting} className="space-y-3.5">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">Pertemuan Ke (Bulan Ini)</label>
                  <input
                    type="text"
                    disabled
                    value={`Pertemuan #${activeSlot.meetingNumber}`}
                    className="w-full px-3 py-2 text-xs border rounded-xl bg-slate-100 text-slate-700 font-bold cursor-not-allowed"
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">Tanggal Mengajar</label>
                  <input
                    type="date"
                    value={inputDate}
                    onChange={(e) => setInputDate(e.target.value)}
                    className="w-full px-3 py-2 text-xs border rounded-xl outline-none focus:ring-2 focus:ring-amber-500 font-medium"
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Nama Tutor</label>
                <input
                  type="text"
                  disabled
                  value={`${currentUser?.name} (Akun Anda)`}
                  className="w-full px-3 py-2 text-xs border rounded-xl bg-slate-100 text-slate-700 font-semibold cursor-not-allowed"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">
                  Materi Pelajaran / Topik Bahasan (Lesson) <span className="text-rose-500">*</span>
                </label>
                <input
                  type="text"
                  placeholder="Misal: Counting Number & Alphabet Review"
                  value={inputLesson}
                  onChange={(e) => setInputLesson(e.target.value)}
                  className="w-full px-3 py-2 text-xs border rounded-xl outline-none focus:ring-2 focus:ring-amber-500"
                  required
                />
              </div>

              {/* KOLOM INPUT LINK YOUTUBE (TEMA NETRAL & OPSIONAL) */}
              <div className="p-3 bg-slate-50 border border-slate-200 rounded-2xl space-y-1.5">
                <label className="block text-xs font-semibold text-slate-700 flex items-center justify-between">
                  <span className="flex items-center gap-1.5">
                    <span>🎬</span> Link Video Pembelajaran (YouTube)
                  </span>
                  <span className="text-[10px] text-slate-400 font-normal">Opsional</span>
                </label>
                <input
                  type="url"
                  placeholder="https://youtu.be/... (kosongkan jika tidak ada)"
                  value={inputVideoUrl}
                  onChange={(e) => setInputVideoUrl(e.target.value)}
                  className="w-full px-3 py-2 text-xs border border-slate-300 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 bg-white"
                />
                <p className="text-[10px] text-slate-400">
                  Dapat dikosongkan. Jika diisi, pastikan tautan YouTube valid dan bisa dibuka.
                </p>
              </div>

              {/* KOLOM CATATAN / NOTE PERKEMBANGAN SISWA */}
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">
                  Catatan Pembelajaran / Note Perkembangan Siswa
                </label>
                <textarea
                  rows={3}
                  placeholder="Tuliskan catatan kelas atau performa murid hari ini (misal: Hari ini Radheya mampu berhitung 1-20 dengan sangat baik)..."
                  value={inputNotes}
                  onChange={(e) => setInputNotes(e.target.value)}
                  className="w-full px-3 py-2 text-xs border rounded-xl outline-none focus:ring-2 focus:ring-amber-500"
                />
              </div>

              <div className="pt-3 flex items-center justify-end gap-2 border-t">
                <button
                  type="button"
                  onClick={() => setActiveSlot(null)}
                  className="px-4 py-2 border rounded-xl text-xs font-semibold text-slate-600 hover:bg-slate-50"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="px-5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-semibold shadow-sm"
                >
                  Simpan ke Jurnal
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL 2: EDIT SESI (KHUSUS ADMIN) */}
      {editingMeeting && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl max-w-md w-full p-6 shadow-2xl space-y-4 animate-in fade-in zoom-in-95 duration-150 max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between border-b pb-3">
              <div>
                <span className="text-[10px] font-bold uppercase tracking-wider text-amber-600">
                  Koreksi / Edit Jurnal (Mode Admin)
                </span>
                <h3 className="font-black text-slate-900 text-base leading-snug">
                  Pertemuan #{editingMeeting.meetingNumber}
                </h3>
              </div>
              <button
                onClick={() => setEditingMeeting(null)}
                className="text-slate-400 hover:text-slate-600 text-lg"
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleSaveEditMeeting} className="space-y-3.5">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">Tanggal Mengajar</label>
                  <input
                    type="date"
                    value={editDate}
                    onChange={(e) => setEditDate(e.target.value)}
                    className="w-full px-3 py-2 text-xs border rounded-xl outline-none focus:ring-2 focus:ring-amber-500 font-medium"
                    required
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-slate-600 mb-1">Ganti Tutor Pengajar</label>
                  <select
                    value={editTutorId}
                    onChange={(e) => setEditTutorId(e.target.value)}
                    className="w-full px-3 py-2 text-xs border border-slate-300 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 bg-white"
                  >
                    {users
                      .filter((u: User) => u.role === 'tutor')
                      .map((t: User) => (
                        <option key={t.id} value={t.id}>
                          {t.name}
                        </option>
                      ))}
                  </select>
                </div>
              </div>

              {/* DROPDOWN KOREKSI ZONA LDR */}
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Zona LDR Pertemuan Ini</label>
                <select
                  value={editLdrZone}
                  onChange={(e) => setEditLdrZone(e.target.value)}
                  className="w-full px-3 py-2 text-xs border border-slate-300 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 bg-white font-medium"
                >
                  <option value="none">Tidak Ada LDR (None)</option>
                  <option value="ldr_10">LDR &gt; 10 KM (Zona 10)</option>
                  <option value="ldr_15">LDR &gt; 15 KM (Zona 15)</option>
                  <option value="ldr_20">LDR &gt; 20 KM (Zona 20)</option>
                  <option value="panti_klungkung">Panti Klungkung</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">
                  Materi Pelajaran / Topik Bahasan (Lesson) <span className="text-rose-500">*</span>
                </label>
                <input
                  type="text"
                  value={editLesson}
                  onChange={(e) => setEditLesson(e.target.value)}
                  className="w-full px-3 py-2 text-xs border rounded-xl outline-none focus:ring-2 focus:ring-amber-500"
                  required
                />
              </div>

              {/* EDIT LINK YOUTUBE (TEMA NETRAL & OPSIONAL) */}
              <div className="p-3 bg-slate-50 border border-slate-200 rounded-2xl space-y-1.5">
                <label className="block text-xs font-semibold text-slate-700 flex items-center justify-between">
                  <span className="flex items-center gap-1.5">
                    🎬 Tautan Video Pembelajaran (YouTube)
                  </span>
                  <span className="text-[10px] text-slate-400 font-normal">Opsional</span>
                </label>
                <input
                  type="url"
                  placeholder="https://youtu.be/... (kosongkan jika tidak ada)"
                  value={editVideoUrl}
                  onChange={(e) => setEditVideoUrl(e.target.value)}
                  className="w-full px-3 py-2 text-xs border border-slate-300 rounded-xl outline-none focus:ring-2 focus:ring-amber-500 bg-white"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">
                  Catatan Pembelajaran / Note Siswa
                </label>
                <textarea
                  rows={3}
                  value={editNotes}
                  onChange={(e) => setEditNotes(e.target.value)}
                  className="w-full px-3 py-2 text-xs border rounded-xl outline-none focus:ring-2 focus:ring-amber-500"
                />
              </div>

              <div className="pt-3 flex items-center justify-end gap-2 border-t">
                <button
                  type="button"
                  onClick={() => setEditingMeeting(null)}
                  className="px-4 py-2 border rounded-xl text-xs font-semibold text-slate-600 hover:bg-slate-50"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="px-5 py-2 bg-amber-500 hover:bg-amber-600 text-white rounded-xl text-xs font-semibold shadow-sm"
                >
                  Simpan Perubahan
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL 3: DETAIL LENGKAP CATATAN PEMBELAJARAN (BACA SELENGKAPNYA) */}
      {viewingNote && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl max-w-lg w-full p-6 shadow-2xl space-y-4 animate-in fade-in zoom-in-95 duration-150">
            {/* Header Modal */}
            <div className="flex items-start justify-between border-b pb-3">
              <div>
                <div className="flex items-center gap-2">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-amber-700 bg-amber-100 px-2 py-0.5 rounded-md border border-amber-300">
                    Sesi #{viewingNote.meetingNumber} (Bulan Ini)
                  </span>
                  <span className="text-[10px] font-extrabold uppercase tracking-wider text-purple-700 bg-purple-100 px-2 py-0.5 rounded-md border border-purple-300">
                    Total Sesi #{viewingNote.cumulativeMeetingNumber}
                  </span>
                </div>
                <h3 className="font-black text-slate-900 text-lg mt-2 leading-snug">
                  {viewingNote.studentName}
                </h3>
                <div className="flex items-center gap-2 text-xs text-slate-500 mt-1">
                  <span>🗓️ {viewingNote.date}</span>
                  <span>•</span>
                  <span>Tutor Pengajar: <strong>{viewingNote.tutorName}</strong></span>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setViewingNote(null)}
                className="text-slate-400 hover:text-slate-600 text-lg p-1.5 hover:bg-slate-100 rounded-xl transition-colors"
              >
                ✕
              </button>
            </div>

            {/* Info Materi */}
            <div className="bg-slate-50 p-3.5 rounded-2xl border border-slate-200">
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block mb-1">
                Materi Pelajaran (Lesson):
              </span>
              <p className="text-xs font-bold text-slate-800">
                {viewingNote.lesson}
              </p>
            </div>

            {/* Isi Catatan Lengkap */}
            <div>
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block mb-1.5">
                Catatan Lengkap Perkembangan Siswa:
              </span>
              <div className="p-4 bg-amber-50/40 rounded-2xl border border-amber-200 text-xs text-slate-700 leading-relaxed max-h-64 overflow-y-auto whitespace-pre-wrap font-medium">
                &ldquo;{viewingNote.notes}&rdquo;
              </div>
            </div>

            {/* Tombol Tutup */}
            <div className="pt-2 flex justify-end border-t border-slate-100">
              <button
                type="button"
                onClick={() => setViewingNote(null)}
                className="px-5 py-2 bg-slate-800 hover:bg-slate-900 text-white rounded-xl text-xs font-semibold transition-all shadow-sm"
              >
                Tutup Catatan
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}